PRAGMA foreign_keys=ON;
CREATE TABLE snapshot_metadata(key TEXT PRIMARY KEY, value_json TEXT NOT NULL);
CREATE TABLE documents(sha256 TEXT PRIMARY KEY, raw_bytes BLOB NOT NULL, format TEXT NOT NULL, purposes_json TEXT NOT NULL);
CREATE TABLE source_records(address TEXT PRIMARY KEY, document_sha256 TEXT NOT NULL REFERENCES documents, pointer TEXT NOT NULL, payload_json TEXT NOT NULL, historical_record_sha256 TEXT, historical_algorithm TEXT, storage_payload_sha256 TEXT NOT NULL, UNIQUE(document_sha256,pointer));
CREATE TABLE units(unit_key TEXT PRIMARY KEY, label TEXT NOT NULL, view_sha256 TEXT NOT NULL REFERENCES documents, request_sha256 TEXT NOT NULL REFERENCES documents, version TEXT NOT NULL, physical_page INTEGER NOT NULL, pdf_sha256 TEXT NOT NULL, native_sha256 TEXT NOT NULL REFERENCES documents, source_json TEXT NOT NULL, provenance_json TEXT NOT NULL, exposure_json TEXT NOT NULL, permissions_json TEXT NOT NULL);
CREATE TABLE documentary_columns(column_key TEXT PRIMARY KEY, unit_key TEXT NOT NULL REFERENCES units, ordinal INTEGER NOT NULL, source_index INTEGER NOT NULL, column_role TEXT NOT NULL, label_json TEXT NOT NULL, payload_json TEXT NOT NULL, UNIQUE(unit_key,ordinal));
CREATE TABLE documentary_rows(row_key TEXT PRIMARY KEY REFERENCES source_records(address), unit_key TEXT NOT NULL REFERENCES units, ordinal INTEGER NOT NULL, local_label_json TEXT NOT NULL, row_class TEXT NOT NULL CHECK(row_class IN ('body','header')), documentary_role_json TEXT NOT NULL, ledger_json TEXT NOT NULL, UNIQUE(unit_key,ordinal));
CREATE TABLE cells(cell_key TEXT PRIMARY KEY REFERENCES source_records(address), unit_key TEXT NOT NULL REFERENCES units, column_key TEXT NOT NULL REFERENCES documentary_columns, cell_class TEXT NOT NULL CHECK(cell_class IN ('body','header')), value_presence TEXT NOT NULL CHECK(value_presence='present'), value_type TEXT NOT NULL, value_json TEXT NOT NULL, display_text TEXT, ledger_json TEXT NOT NULL);
CREATE TABLE row_cells(row_key TEXT NOT NULL REFERENCES documentary_rows, ordinal INTEGER NOT NULL, cell_key TEXT NOT NULL UNIQUE REFERENCES cells, PRIMARY KEY(row_key,ordinal));
CREATE TABLE documentary_metadata(metadata_key TEXT PRIMARY KEY REFERENCES source_records(address), unit_key TEXT NOT NULL REFERENCES units, ordinal INTEGER NOT NULL, kind TEXT NOT NULL, ledger_json TEXT NOT NULL);
CREATE TABLE words(word_key TEXT PRIMARY KEY REFERENCES source_records(address), native_sha256 TEXT NOT NULL REFERENCES documents, word_index INTEGER NOT NULL, text TEXT NOT NULL, span_json TEXT NOT NULL, bbox_json TEXT NOT NULL, frame TEXT NOT NULL);
CREATE TABLE unit_words(unit_key TEXT NOT NULL REFERENCES units, word_key TEXT NOT NULL REFERENCES words, anchor_record TEXT NOT NULL REFERENCES source_records(address), PRIMARY KEY(unit_key,word_key));
CREATE TABLE word_links(word_key TEXT NOT NULL REFERENCES words, ordinal INTEGER NOT NULL, kind TEXT NOT NULL, record_key TEXT NOT NULL REFERENCES source_records(address), PRIMARY KEY(word_key,kind,ordinal));
CREATE TABLE owner_words(owner_key TEXT NOT NULL REFERENCES source_records(address), ordinal INTEGER NOT NULL, word_key TEXT NOT NULL REFERENCES words, PRIMARY KEY(owner_key,ordinal));
CREATE TABLE metadata_words(metadata_key TEXT NOT NULL REFERENCES documentary_metadata, ordinal INTEGER NOT NULL, word_key TEXT NOT NULL REFERENCES words, PRIMARY KEY(metadata_key,ordinal));
CREATE TABLE contexts(context_key TEXT PRIMARY KEY REFERENCES source_records(address), unit_key TEXT NOT NULL UNIQUE REFERENCES units, kind TEXT NOT NULL, kind_basis TEXT NOT NULL);
CREATE TABLE segments(segment_key TEXT PRIMARY KEY REFERENCES source_records(address), owner_key TEXT NOT NULL REFERENCES source_records(address), ordinal INTEGER NOT NULL, exact_text TEXT NOT NULL, own_span_json TEXT NOT NULL, span_frame TEXT NOT NULL, UNIQUE(owner_key,ordinal));
CREATE TABLE assertions(assertion_key TEXT PRIMARY KEY REFERENCES source_records(address), unit_key TEXT NOT NULL REFERENCES units, source_record TEXT NOT NULL REFERENCES source_records(address), attribution_json TEXT NOT NULL, stage_presence TEXT NOT NULL, stage_json TEXT, payload_json TEXT NOT NULL);
CREATE TABLE assertion_links(owner_key TEXT NOT NULL REFERENCES source_records(address), ordinal INTEGER NOT NULL, assertion_key TEXT NOT NULL REFERENCES assertions, PRIMARY KEY(owner_key,ordinal));
CREATE TABLE qualifiers(qualifier_key TEXT PRIMARY KEY REFERENCES source_records(address), unit_key TEXT NOT NULL REFERENCES units, context_key TEXT NOT NULL REFERENCES contexts, ordinal INTEGER NOT NULL, kind TEXT NOT NULL, target_kind TEXT NOT NULL, target_column TEXT REFERENCES documentary_columns(column_key), target_json TEXT NOT NULL, display_text TEXT, contiguous_json TEXT NOT NULL, resolution_json TEXT NOT NULL);
CREATE TABLE dependencies(dependency_key TEXT PRIMARY KEY REFERENCES source_records(address), unit_key TEXT NOT NULL REFERENCES units, ordinal INTEGER NOT NULL, name TEXT NOT NULL, state TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE evidence_links(owner_key TEXT NOT NULL REFERENCES source_records(address), ordinal INTEGER NOT NULL, source_record TEXT REFERENCES source_records(address), reference_json TEXT NOT NULL, PRIMARY KEY(owner_key,ordinal));
CREATE TABLE unresolved_references(owner_key TEXT NOT NULL REFERENCES source_records(address), ordinal INTEGER NOT NULL, reference_json TEXT NOT NULL, reason TEXT NOT NULL, PRIMARY KEY(owner_key,ordinal));
CREATE VIEW v_body_rows AS SELECT r.*,u.label,u.physical_page FROM documentary_rows r JOIN units u USING(unit_key) WHERE r.row_class='body';
CREATE VIEW v_body_cells AS SELECT c.*,r.row_key,r.ordinal AS row_ordinal,r.local_label_json,r.documentary_role_json,rc.ordinal AS cell_ordinal,col.column_role,col.source_index,col.label_json,u.physical_page,u.label FROM cells c JOIN row_cells rc USING(cell_key) JOIN documentary_rows r USING(row_key) JOIN documentary_columns col USING(column_key) JOIN units u ON u.unit_key=c.unit_key WHERE c.cell_class='body';
CREATE VIEW v_cell_qualifiers AS SELECT c.cell_key,q.qualifier_key,q.kind,q.target_kind,col.column_role FROM cells c JOIN documentary_columns col USING(column_key) JOIN qualifiers q ON q.unit_key=c.unit_key AND (q.target_kind='table_proposal' OR (q.target_kind='column' AND q.target_column=c.column_key)) WHERE c.cell_class='body';
CREATE VIEW v_cell_context AS SELECT c.cell_key,c.unit_key,x.context_key,x.kind FROM cells c JOIN contexts x USING(unit_key);
